insert into public.app_settings (key, value) values
  ('catalog_version', '{"version":"2026-08-v9","created":"2026-08-16","description":"222xx küresel makaralı rulman serisi BÜYÜK BOYLARA açıldı: 22228 · 22230 · 22232 · 22234 · 22236, her boy hem CC/W33 (silindirik delik) hem CCK/W33 (konik delik) olarak — 10 satır, delik 140-180 mm. Seri 22226 E''de bitiyordu ve daha büyük tambur/teker mili isteyen işlerde katalogdan seçim yapılamıyordu. Kaynak yine workspace kökündeki SKF PUB BU/P1 17000 EN kataloğudur (basılı s.800-804); skf.com''dan veri çekilmemiştir. — Önceki sürüm (2026-08-v8, 2026-08-09): \"Diğer kataloglar\" klasöründeki 16 üretici PDF''i işlendi. HALAT kataloğu ilk kez eklendi (CASAR 16 ürün + Haşçelik 2 + OLIVEIRA 2 + DIEPA 1 = 21 dosya / 1722 satır); redüktör kataloğuna POLAT PCS (kaldırma), YILMAZ K ve Planet, SEW X / X..e-HC / R-F-K-S-W eklendi (40.696 satır); motor kataloğuna SEW DRN (57 satır) girdi. POLAT PD/PM, SEW GEARHOIST ve YILMAZ V kataloglarında redüktörün kendi anma momenti basılı olmadığı için (yalnız motorlu tablo yayımlıyorlar) satır üretilmedi — gerekçesi scripts/catalog-extract/README.md''de","sources":{"couplings":"ÖZGÜN 28 tip / 387 satır (ozgun katalog 2019 1-b.pdf) · SIBRE 11 seri / 94 satır (02_SIBRE_Coupling-catalogue.pdf) · JAURE MT alt serileri MT/MTS/MTG/MTG-HD/MTF/MTFE/MTES + TCBR / 107 satır (JAURE MT Series_Gear Coupling.pdf, TCBR_Barrel Coupling.pdf) — toplam 47 dosya / 588 satır, 2026-08-06","wheels":"FEM 1.001 standart boyutları","ropes":"CASAR Special Wire Ropes 02/2024 — 16 ürün / 1213 satır, öz tipi ve dönmeye direnç nitelikleri katalogun kendi Rope Properties matrisinden (s.C12-C13) · Haşçelik H 18 LRC (21) ve H 8K PI (60) ürün föyleri · OLIVEIRA DP 8 K PPI (34) ve HD 8 K PPI (82), Güven Çelik Halat 04/2019 · DIEPA H 43 (312) — toplam 21 dosya / 1722 satır, 2026-08-09. Eski hascelik_6x36 ve izmit_6x36 (TS EN 12385 tabloları) korundu","motors":"GAMAK (148 motor, GAMAK Teknik Katalog 2022) + ABB (115 motor, M3BP 9AKK105944 EN 02-2020) + INNOMOTICS (100 motor, SIMOTICS SD 1LE1503/1LE1603, Siemens D 81.1 12/2021) — hepsinde 2/4/6/8 kutup ve boyut tablosundan okunan mil çapı, toplam 363 satır, 2026-08-06 · SEW DRN/DR2S 400 V 50 Hz (57 satır, DRN.. Gearmotors 24832936/EN 09/2018 böl.13; mil ucu çapı IEC 60072-1''den, shaft_source alanında belirtilir), 2026-08-09","reducers":"YILMAZ D serisi (yürütme, 579) + M/N serisi (yürütme, 1292) + H/B serisi (kaldırma, 5407) — motorsuz güç devir tabloları, 2026-08-06 · SIMOGEAR paralel (yürütme, 488) · POLAT PCS kaldırma (150, motorsuz performans tabloları, 2024 katalog) · YILMAZ K serisi (1130) ve Planet P/PK/PS (22416, anma momenti ömüre bağlı) · SEW X serisi X.F/X.K/X.T (15432) ve X..e/HC kaldırma (20) ve R/F/K/S/W yürütme (1548) — 2026-08-09","flender_reducers":"FLENDER MD 20.1 universal H1-H4 helisel ve B2-B4 konik-helisel: 146 tip/boyut, nominal T2N ve çevrim aralığı; her biri kaldırma ve yürütme kataloglarında sunulur — MD 20.1 2018, s.16-17, 2026-08-07","brakes":"SIBRE TE/USB/SHI + DERELİ DYF + GALVI NEWCOMEN N.HYD / NV.HYD (33 kasnak freni, DIN 15435, tüm geometri mm) — Galvi Kasnak Fren.pdf, 2026-08-07","bearings":"SKF Rolling Bearings PUB BU/P1 17000 EN (Haziran 2018): 60xx / 62xx / 63xx sabit bilyalı, 222xx / 223xx küresel makaralı, 512xx eksenel bilyalı, NU / NJ silindirik makaralı — 320 satır, tüm sınır ölçüleri mm, 2026-08-07 · 2026-08-16: 222xx serisine 22228 / 22230 / 22232 / 22234 / 22236 eklendi (basılı s.800-804), her boy CC/W33 + CCK/W33 olarak — toplam 330 satır. SKF E tasarımını 22226''ya kadar basar; üstü CC/W33''tür ve bu bir tasarım değişikliğidir, aynı ürünün başka yazımı değil — 22228 CC/W33''ün dinamik yükü (743 kN) 22226 E''ninkinden (758 kN) DÜŞÜKTÜR, çünkü E bir SKF Explorer tasarımıdır. Konik delikli eşler AYRI SATIRDIR ve seri alanında ayrılır (''222xx Küresel Makaralı (Konik Delik)''): sayıları aynıdır ama montajı aynı değildir, konik delik adaptör manşonu ister.","bearing_housings":"SKF Bearing Housings and Roller Bearing Units PUB BU/P1 13186/1 EN (Şubat 2015), bölüm 2.3: 222xx / 223xx küresel makaralı rulmanlar için SNL/SE silindirik yataklama eşleşmeleri — 28 satır, tüm ölçüler mm, 2026-08-07","buffers":"SIBRE SP hidrolik (33 ürün + 216 hücrelik kuvvet matrisi + 169 kısma iğnesi) — SIBRE Produktkatalog2022_Puffer_SP.pdf s.18-22 · Conductix-Wampfler kauçuk Program 0170 (67) + hücresel Program 0180 (55) — KAT0170-0002-EN · kauçuk yük diyagramları 10 çap (enerji-strok + kuvvet-strok eğrileri) — KAT0170-0003-EN · firma Excel''inden 11 teyit EDİLMEMİŞ ''Type NN HD'' satırı ayrı dosyada, 2026-08-06 — toplam 166 satır","festoons":"Conductix-Wampfler KAT0320-0003b-EN (2016) Festoon Systems for I-Beams — Program 0314 plastik arabalar (34 satır, s.4-9) + Program 0320/0325/0330 çelik arabalar (58 satır, s.11-16), tümü ölçü ve kiriş uyumluluğuyla · Vasel Cat.4b/52-E I-Profil Grubu broşürü — VS2005''in dokuz araba tipi, VS2010/VS2015/VS2020 (17 satır, s.2-3) + yalnız fotoğrafla verilen 2050/2060/2070 ve VS25-S2/VS26-S3/VS26-S4 aileleri (6 satır) — toplam 115 satır, 2026-08-08"},"notes":"Redüktörlerde application alanı kullanım grubunu taşır (kaldirma | yurutme); katalog seçicisinde bölüme göre kilitlidir. İzin verilen radyal yükler kN olarak saklanır. MOTOR: shaft_diameter_mm seed''de shaft_mm olarak yazılır ve 2.4/5.4 bölümlerinde motorShaftMm alanını doldurur; seri satırın kendi series alanından okunur, devir katalogun GERÇEK yüklü devridir (senkron devire yuvarlanmaz). KAPLİN: seri ve coupling_type satırın kendi alanlarından okunur — JAURE MT alt serileri ayrı ayrı seçilebilir; tambur kaplini bölümü drum + barrel kodlarına, motor kaplini bölümü gear/flexible/pin/disc/brake kodlarına kilitlidir. TAMPON: üç aile tek kind altındadır; enerji birimi ortak anahtarda kJ''dir (kauçuk katalog J basar, seed 1 J = 0,001 kJ ile çevirir, ham değer energy_j altında kalır). Kauçuk ve hücreselde strok katalogda basılı değildir, s = yükseklik · izin verilen sıkışma% / 100 ile türetilir. Kauçuk doğrusal değildir; ara nokta satıra iliştirilen energy_curve / force_curve dizilerinden okunur (yalnız conductix_curves.json''un applies_to_models listesindeki 13 ürün kodu; Ø40/Ø50/Ø63 eğrilerinin karşılığı olan silindirik ürün yoktur ve konik ürüne BAĞLANMAMIŞTIR). firma_excel_buffers.json satırları unverified: true taşır ve seçicide uyarı gösterilir. FESTON: ürün kimliği KABLO ARABASININ sipariş kodudur (Conductix 032252-250x160, Vasel VS2005A-CT80); program/seri kodu attrs.series altındadır ve seçicinin ikinci süzgeç adımıdır. Conductix satırlarının tamamı katalogdan doğrulanmıştır. Vasel''de PARÇA KODLARI broşürden birebirdir ama TAŞIYICI YÜKÜ ve HIZ broşürde YAYIMLANMAMIŞTIR: o iki alan üretici ürün sayfalarından gelir, satır unverified: true taşır ve load_source alanı kaynağı yazar. Broşürde yalnız fotoğrafla verilen Vasel aileleri parça kodu ve kablo formu taşımaz; catalog_ref alanı mühendisi Cat.4b/52''nin ilgili sayfasına yönlendirir. Önceki veri kümesindeki VS25-S1 broşürün ürün dizisinde yoktur, kaldırılmıştır."}'::jsonb)
